using UnityEngine;using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Match;
namespace Alterverse.AI
{
[RequireComponent(typeof(Health),typeof(MobaBotBrain),typeof(BotLanePlan))][RequireComponent(typeof(BotTargetSensor))]public sealed class MobaBotMover:MonoBehaviour
{
[SerializeField]private float fallbackMoveSpeed=3.35f,laneStopDistance=.35f,chaseLimit=12f,turnSpeed=7f;private const float ArenaHalfWidth=40f,ArenaHalfHeight=33f;private Health health;private MobaBotBrain brain;private BotLanePlan lanePlan;private BotTargetSensor sensor;private HeroCombatProfile profile;private PlanetBuffReceiver planetBuff;private float nextObjectiveScan;private DimensionPlanet objective;private Vector3 velocity;
private float MoveSpeed=>(profile!=null?profile.MoveSpeed:fallbackMoveSpeed)*(planetBuff!=null?planetBuff.MoveSpeedMultiplier:1f);private float CombatStop=>profile!=null?Mathf.Max(1.15f,profile.AttackRange*.78f):1.4f;private void Awake(){health=GetComponent<Health>();brain=GetComponent<MobaBotBrain>();lanePlan=GetComponent<BotLanePlan>();sensor=GetComponent<BotTargetSensor>();profile=GetComponent<HeroCombatProfile>();planetBuff=GetComponent<PlanetBuffReceiver>();}
private void Update(){if(Time.timeScale<=0f||health==null||health.IsDead||brain==null||lanePlan==null){velocity=Vector3.zero;return;}if(planetBuff==null)planetBuff=GetComponent<PlanetBuffReceiver>();ScanObjective();Vector3 destination=lanePlan.GetDestination(brain.State);float stopDistance=laneStopDistance;Health target=sensor!=null?sensor.CurrentTarget:null;if(target!=null&&!target.IsDead&&brain.State==MobaBotBrain.BotState.Fight){Vector3 d=target.transform.position-transform.position;d.y=0;if(d.sqrMagnitude<=chaseLimit*chaseLimit){destination=target.transform.position;stopDistance=CombatStop;}}else if(brain.State==MobaBotBrain.BotState.Lane&&objective!=null&&objective.Available&&ShouldRotate()){destination=objective.transform.position;stopDistance=2.2f;}MoveToward(destination,stopDistance);}
private void ScanObjective(){if(Time.time<nextObjectiveScan)return;nextObjectiveScan=Time.time+1;objective=null;float best=float.MaxValue;foreach(DimensionPlanet p in FindObjectsByType<DimensionPlanet>()){if(!p.Available)continue;float d=(p.transform.position-transform.position).sqrMagnitude;if(d<best){best=d;objective=p;}}}private bool ShouldRotate(){if(objective==null)return false;float d=(objective.transform.position-transform.position).sqrMagnitude;if(d>26f*26f)return false;int slot=Mathf.Abs(gameObject.name.GetHashCode())%5;return slot<2||d<10f*10f;}
public void ResetMotion(){velocity=Vector3.zero;objective=null;nextObjectiveScan=0;}
private void MoveToward(Vector3 destination,float stopDistance){Vector3 delta=destination-transform.position;delta.y=0;if(delta.sqrMagnitude<=stopDistance*stopDistance){velocity=Vector3.zero;return;}if(Vector3.Dot(velocity,delta)<0f)velocity=Vector3.zero;Vector3 desired=delta.normalized*MoveSpeed;velocity=Vector3.Lerp(velocity,desired,Mathf.Clamp01(6f*Time.deltaTime));Vector3 step=Vector3.ClampMagnitude(velocity*Time.deltaTime,Mathf.Max(0f,delta.magnitude-stopDistance));Vector3 next=transform.position+step;next.x=Mathf.Clamp(next.x,-ArenaHalfWidth,ArenaHalfWidth);next.z=Mathf.Clamp(next.z,-ArenaHalfHeight,ArenaHalfHeight);transform.position=next;if(velocity.sqrMagnitude>.05f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(velocity.normalized),turnSpeed*Time.deltaTime);}
}
}
